sys_script.script:
(function executeRule(current, previous) {

    /*
     * Make sure the registration has a student
     */
    if (current.student.nil()) {
        return;
    }

    /*
     * Get Student sys_id
     */
    var userSysId = current.student.toString();

    /*
     * Count ALL registrations for this student
     */
    var registrations = new GlideAggregate(
        'x_snc_campus_con_0_registrations'
    );

    registrations.addQuery(
        'student',
        userSysId
    );

    registrations.addAggregate('COUNT');

    registrations.query();

    var registrationCount = 0;

    if (registrations.next()) {

        registrationCount = parseInt(
            registrations.getAggregate('COUNT'),
            10
        );

    }

    /*
     * Reliability Score
     *
     * 0 registrations = 0
     * 1 registration  = 10
     * 2 registrations = 20
     * 3 registrations = 30
     *
     * No maximum limit.
     */
    var score =
        registrationCount * 10;


    /*
     * Find Student Profile
     */
    var profile = new GlideRecord(
        'x_snc_campus_con_0_student_profile'
    );

    profile.addQuery(
        'student',
        userSysId
    );

    profile.setLimit(1);

    profile.query();


    if (profile.next()) {

        profile.setValue(
            'reliability_score',
            score
        );

        /*
         * Prevent this update from
         * triggering unnecessary workflow
         */
        profile.setWorkflow(false);

        profile.update();

    }

})(current, previous);
